-------------------------------------------------------------------------------
-- Notes:  Specifies a unique 8-bit identifier for each level in the game. Many
--         systems use this unique identifier to compare one level to another.
--         For example, the SynchVarBarn uses it to determine whether synch vars
--         sent from a remote client should be read or ignored. 
-- 
--         In the future, this file should be automatically generated by the
--         build system, and might include some additional versioning 
--         component about the level contents. 
--
-- Author: Nick Clark
-- Date C: 8-25-2010
-------------------------------------------------------------------------------

levelUids = 
{	["Level_Graveyard"] = 0
,	["Level_Barrens"] = 1
,	["Level_Desert"] = 2
,	["Level_Canyon"] = 3
,	["Level_Cave"] = 4
,	["Level_Ruins"] = 5
,	["Level_Mountain"] = 6
,	["Level_Summit"] = 7
,	["Level_Credits"] = 8
,	["Level_Bryan"] = 9
,	["Level_Matt"] = 10
,	["Level_Chris"] = 11
}

levelNames = {}
for name, uid in pairs( levelUids ) do levelNames[ uid ] = name end

function GetLevelUid( levelName )
	if levelName == "" then return 0 end
	local levelUid = levelUids[ levelName ]
	assert( levelUid ~= nil )
	return levelUid
end

function GetLevelName( levelUid )
	local levelName = levelNames[ levelUid ]
	assert( levelName ~= nil )
	return levelName
end
